        double annual=r((lower+upper)/2*100,6),monthly=Math.pow(1+annual/100,1.0/12)-1,assets=capital;JSONArray points=new JSONArray().put(obj("month",0,"assets",r(assets),"contributions",r(capital),"investmentGain",0));
        for(int i=1;i<=count;i++){assets=assets*(1+monthly)+contribution;double added=capital+contribution*i;points.put(obj("month",i,"assets",r(assets),"contributions",r(added),"investmentGain",r(assets-added)));}
        double added=capital+contribution*count;return obj("months",count,"annualRatePercent",annual,"monthlyRatePercent",r(monthly*100,6),"totalContributions",r(added),"finalAssets",r(assets),"investmentGain",r(assets-added),"points",points);
