        String level=equity==0?"unavailable":top1>35||hhi>2500?"high":top1>20||hhi>1500?"medium":"balanced";JSONArray rows=new JSONArray();for(JSONObject p:weighted)rows.put(p.put("weightPercent",r(p.getDouble("weightPercent"))).put("equityWeightPercent",r(p.getDouble("equityWeightPercent"))));
        return obj("totalAssets",r(total),"equityValue",r(equity),"cashBalance",r(cash),"cashPercent",r(total>0?cash/total*100:0),"top1Percent",r(top1),"top3Percent",r(top3),"hhi",equity>0?r(hhi):null,"positionCount",rows.length(),"level",level,"positions",rows);
