    private static JSONObject lossPath(JSONObject x)throws JSONException{double initial=positive(x,"initialEquity"),risk=positive(x,"riskPercent");need(risk<100,"风险比例必须小于100%");int count=integer(x,"consecutiveLosses",0,1000);double equity=initial;JSONArray points=new JSONArray().put(obj("step",0,"equity",r(equity),"lossAmount",0));for(int i=1;i<=count;i++){double loss=equity*risk/100;equity-=loss;points.put(obj("step",i,"equity",r(equity),"lossAmount",r(loss)));}double d=(initial-equity)/initial*100;return obj("initialEquity",r(initial),"finalEquity",r(equity),"drawdownPercent",r(d),"recoveryPercent",d>=100?null:r(d/(100-d)*100),"points",points,"recoveryUnavailable",d>=100);}
