        if(k<=n){double[] states=new double[k];states[0]=1;for(int i=0;i<n;i++){double sum=0;for(double s:states)sum+=s;double[] next=new double[k];next[0]=sum*p;for(int j=0;j<k-1;j++)next[j+1]+=states[j]*q;states=next;}double noRun=0;for(double s:states)noRun+=s;probability=Math.max(0,Math.min(1,1-noRun));}
