    private static JSONObject equityPath(JSONObject x)throws JSONException{double initial=positive(x,"initialCapital"),equity=initial,high=initial,maximum=0;JSONArray values=array(x,"pnlValues",1,500),points=new JSONArray().put(obj("step",0,"pnl",0,"equity",r(initial),"drawdownPercent",0));int underwaterStart=-1,longest=0,underwaterCount=0;for(int i=0;i<values.length();i++){double pnl=number(values.get(i),"盈亏样本");equity+=pnl;int step=i+1;if(equity>=high){if(underwaterStart>=0)longest=Math.max(longest,step-underwaterStart+1);high=equity;underwaterStart=-1;}else{underwaterCount++;if(underwaterStart<0)underwaterStart=step;}double d=(high-equity)/high*100;maximum=Math.max(maximum,d);points.put(obj("step",step,"pnl",r(pnl),"equity",r(equity),"drawdownPercent",r(d,6)));}if(underwaterStart>=0)longest=Math.max(longest,values.length()-underwaterStart+1);return obj("initialCapital",r(initial),"finalCapital",r(equity),"netPnl",r(equity-initial),"maximumDrawdownPercent",r(maximum,6),"longestUnderwaterSpan",longest,"underwaterObservationCount",underwaterCount,"capitalDepleted",equity<=0,"points",points);}
